class Counter extends Map<string, number> {
  inc(k: string): void { this.set(k, (this.get(k) ?? 0) + 1); }
}
function main(): void {
  const c = new Counter(); c.inc("a"); c.inc("a"); c.inc("b");
  console.log(c.get("a"), c.size, c instanceof Map, c instanceof Counter);
  console.log(c);
}
